#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long val = strtol(argv[1], &endptr, 10);
    // Check conversion succeeded and consumed entire string
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    // Reject negative or zero values
    if (val <= 0) {
        puts("BAD_INPUT");
        return 0;
    }
    // Upper bound as observed in the original binary (30)
    if (val > 30) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    // Compute Catalan numbers up to C_{val-1}
    unsigned long long cat[31]; // enough for up to 30
    cat[0] = 1ULL;
    for (int i = 1; i < val; ++i) {
        unsigned long long sum = 0ULL;
        for (int j = 0; j < i; ++j) {
            sum += cat[j] * cat[i - 1 - j];
        }
        cat[i] = sum;
    }
    // The original program prints the (val-1)th Catalan number.
    printf("%llu\n", cat[val - 1]);
    return 0;
}
